def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    opp_d = 0
    for _, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    if opp_c == 0:
        return 'D'

    w5 = min(5, n)
    r5 = sum(1 for _, b in history[-w5:] if b == 'D')

    w10 = min(10, n)
    r10 = sum(1 for _, b in history[-w10:] if b == 'D')

    w20 = min(20, n)
    r20 = sum(1 for _, b in history[-w20:] if b == 'D')

    if (opp_d * 4 >= n * 3 or r10 >= 8 or (n >= 20 and r20 >= 14)) and not (n >= 15 and r10 == 0 and opp_last == 'C'):
        return 'D'

    forgive = 0
    for a, b in history:
        if a == 'D' and b == 'C':
            forgive += 1

    punish_recent = 0
    for a, b in history[-w20:]:
        if a == 'D' and b == 'D':
            punish_recent += 1

    if opp_last == 'D':
        if my_last == 'C':
            return 'D'

        if n < 95 and opp_c * 2 >= n and r10 <= 4 and r5 <= 2:
            return 'C'
        if n < 95 and opp_c * 4 >= n * 3 and r5 <= 1:
            return 'C'
        return 'D'

    if my_last == 'C':
        return 'C'

    streak = 0
    for a, b in reversed(history):
        if a == 'D' and b == 'C':
            streak += 1
        else:
            break

    if (n < 90 and punish_recent == 0 and forgive >= 1 and
        opp_d <= max(2, n // 10) and r10 <= 1 and streak < 4):
        return 'D'

    return 'C'
